import numpy as np
from sklearn.manifold import _mds as mds

# Create a dissimilarity matrix with very small value that causes NaN in isotonic regression
dis = np.array([
    [0.0, 1.732050807568877, 1.7320508075688772],
    [1.732050807568877, 0.0, 6.661338147750939e-16],
    [1.7320508075688772, 6.661338147750939e-16, 0.0]
])

init = np.array([
    [0.08665881585055124, 0.7939114643387546],
    [0.9959834154297658, 0.7555546025640025],
    [0.8766008278401566, 0.4227358815811242]
])

try:
    embedding, stress = mds.smacof(dis, init=init, metric=False, n_init=1)
    probe('isotonic_error_occurred', 0)  # No error means 0
except ValueError as e:
    if 'NaN' in str(e) or 'Input contains NaN' in str(e):
        probe('isotonic_error_occurred', 1)  # Error occurred
    else:
        probe('isotonic_error_type', 2)  # Different error
except Exception as e:
    probe('isotonic_error_type', 3)  # Unexpected error

